const fs = require('fs');
const path = require('path');

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

function slug(value) {
  const s = String(value || '').toLowerCase().replace(/[^a-z0-9_-]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
  if (!s) throw new Error('product_id is required');
  return s;
}
function requiredEnv(name) {
  const value = $env[name];
  if (!value) throw new Error(`${name} environment variable is required`);
  return value;
}
function toBool(value, defaultValue = false) {
  if (value === true || value === false) return value;
  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    if (normalized === 'true') return true;
    if (normalized === 'false') return false;
  }
  return defaultValue;
}
function normalizeLocalRoot(value) {
  return String(value).replace(/\\/g, '/').replace(/\/+$/, '');
}
function repoPathUrl(repoPath) {
  return encodeURIComponent(repoPath).replace(/%2F/g, '/');
}
function cdnUrl(owner, repo, branch, repoPath) {
  const encodedPath = repoPath.split('/').map(part => encodeURIComponent(part)).join('/');
  return `https://cdn.jsdelivr.net/gh/${owner}/${repo}@${branch}/${encodedPath}`;
}
function readFileBase64(filePath) {
  const stat = fs.statSync(filePath);
  const maxBytes = 95 * 1024 * 1024;
  if (stat.size > maxBytes) {
    throw new Error(`File is too large for GitHub Contents API (${stat.size} bytes): ${filePath}`);
  }
  return fs.readFileSync(filePath).toString('base64');
}
function summarizeError(error) {
  return error?.message || String(error);
}
async function githubRequest(method, url, token, body, label) {
  const options = {
    method,
    url,
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      'User-Agent': 'n8n-local-video-automation'
    },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 120000
  };
  if (body !== undefined) {
    options.headers['Content-Type'] = 'application/json';
    options.body = body;
  }

  let lastError;
  for (let attempt = 1; attempt <= 5; attempt++) {
    try {
      const response = await helpers.httpRequest(options);
      const statusCode = Number(response?.statusCode || 0);
      if (![408, 409, 429, 500, 502, 503, 504].includes(statusCode)) {
        return response;
      }
      lastError = new Error(`GitHub ${method} retryable HTTP ${statusCode} for ${label}: ${JSON.stringify(response.body)}`);
    } catch (error) {
      lastError = error;
    }

    if (attempt < 5) {
      await sleep(1000 * attempt * attempt);
    }
  }
  throw new Error(`GitHub ${method} failed after retries for ${label}: ${summarizeError(lastError)}`);
}

async function githubGet(owner, repo, branch, repoPath, token) {
  const url = `https://api.github.com/repos/${owner}/${repo}/contents/${repoPathUrl(repoPath)}?ref=${encodeURIComponent(branch)}`;
  const response = await githubRequest('GET', url, token, undefined, repoPath);
  if (response.statusCode === 404) return null;
  if (response.statusCode < 200 || response.statusCode >= 300) {
    throw new Error(`GitHub GET failed ${response.statusCode} for ${repoPath}: ${JSON.stringify(response.body)}`);
  }
  return response.body;
}

async function githubPut(owner, repo, branch, repoPath, contentBase64, message, token, skipIfUnchanged = false) {
  const existing = await githubGet(owner, repo, branch, repoPath, token);
  if (skipIfUnchanged && existing?.content) {
    const currentContent = String(existing.content).replace(/\s/g, '');
    const nextContent = String(contentBase64).replace(/\s/g, '');
    if (currentContent === nextContent) {
      return { unchanged: true, sha: existing.sha };
    }
  }
  const body = { message, content: contentBase64, branch };
  if (existing?.sha) body.sha = existing.sha;
  const url = `https://api.github.com/repos/${owner}/${repo}/contents/${repoPathUrl(repoPath)}`;
  const response = await githubRequest('PUT', url, token, body, repoPath);
  if (response.statusCode < 200 || response.statusCode >= 300) {
    throw new Error(`GitHub PUT failed ${response.statusCode} for ${repoPath}: ${JSON.stringify(response.body)}`);
  }
  return response.body;
}

const input = $json.body ?? $json;
const productId = slug(input.product_id);
const owner = input.owner || $env.GITHUB_OWNER || 'fye2552';
const repo = input.repo || $env.GITHUB_REPO || 'video_automation_repo';
const branch = input.branch || $env.GITHUB_BRANCH || 'main';
const token = requiredEnv('GITHUB_TOKEN');
const localProductsRoot = normalizeLocalRoot($env.N8N_LOCAL_PRODUCTS_DIR || 'E:/n8n-video-gemini/local_products');
const projectRoot = normalizeLocalRoot(path.dirname(localProductsRoot));
const localDir = `${localProductsRoot}/${productId}`;
const profilePath = path.join(localDir, 'product_profile.yaml');
if (!fs.existsSync(profilePath)) throw new Error(`product_profile.yaml is required: ${profilePath}`);
const planPath = path.join(localDir, 'plan_batch_001.md');
const imageSourceDirs = [
  path.join(localDir, 'images'),
  path.join(localDir, 'reference_images'),
  path.join(localDir, 'skill_a', 'images'),
  path.join(localDir, 'skill_a', 'reference_images'),
  // Compatibility fallback: some product packs keep source images directly in the product root.
  localDir
];
const warnings = [];
const uploads = [];
let imageUploadWarning = '';
const activeSkill = input.active_skill || 'skill_c';

if (activeSkill === 'skill_e') {
  const skillEPath = normalizeLocalRoot($env.N8N_SKILL_E_PATH || path.join(projectRoot, 'SKILL-E.md'));
  if (!fs.existsSync(skillEPath) || !fs.statSync(skillEPath).isFile()) {
    throw new Error(`Skill E source file is required: ${skillEPath}`);
  }
  uploads.push({
    local: skillEPath,
    repoPath: 'skills/skill_e.md',
    skipIfUnchanged: true,
    isSkill: true
  });
}

uploads.push({ local: profilePath, repoPath: `products/${productId}/skill_a/product_profile.yaml` });
if (fs.existsSync(planPath)) {
  uploads.push({ local: planPath, repoPath: `products/${productId}/skill_a/plan_batch_001.md` });
} else {
  uploads.push({ contentBase64: Buffer.from('', 'utf8').toString('base64'), repoPath: `products/${productId}/skill_a/plan_batch_001.md` });
  warnings.push(`plan_batch_001.md not found for ${productId}; uploaded empty optional file`);
}
const discoveredImages = [];
const seenImageNames = new Set();
for (const sourceDir of imageSourceDirs) {
  if (!fs.existsSync(sourceDir) || !fs.statSync(sourceDir).isDirectory()) continue;
  const imageNames = fs.readdirSync(sourceDir)
    .filter(name => /\.(png|jpe?g|webp)$/i.test(name))
    .sort((a, b) => a.localeCompare(b));
  for (const name of imageNames) {
    const key = name.toLowerCase();
    if (seenImageNames.has(key)) continue;
    seenImageNames.add(key);
    discoveredImages.push({ local: path.join(sourceDir, name), name, sourceDir });
  }
}
if (!discoveredImages.length) {
  imageUploadWarning = 'No local images found under images/reference_images paths';
  warnings.push(imageUploadWarning);
} else {
  for (const image of discoveredImages) {
    uploads.push({
      local: image.local,
      repoPath: `products/${productId}/images/${image.name}`,
      isImage: true
    });
  }
  const standardNames = ['product_white_bg.png', 'product_detail_side.png', 'product_function.png'];
  const missingStandardNames = standardNames.filter(name => !seenImageNames.has(name));
  if (missingStandardNames.length) {
    warnings.push(`Standard image filenames not found: ${missingStandardNames.join(', ')}; original image filenames were uploaded without renaming`);
  }
}
uploads.push({ contentBase64: Buffer.from('', 'utf8').toString('base64'), repoPath: `history/products/${productId}/index.jsonl`, createOnly: true });

const uploaded = [];
const uploadedImages = [];
for (const upload of uploads) {
  if (upload.createOnly) {
    const existing = await githubGet(owner, repo, branch, upload.repoPath, token);
    if (existing) {
      uploaded.push({ path: upload.repoPath, skipped: true });
      continue;
    }
  }
  const contentBase64 = upload.contentBase64 !== undefined ? upload.contentBase64 : readFileBase64(upload.local);
  const putResult = await githubPut(
    owner,
    repo,
    branch,
    upload.repoPath,
    contentBase64,
    `Upload ${upload.repoPath}`,
    token,
    upload.skipIfUnchanged === true
  );
  const bytes = upload.local ? fs.statSync(upload.local).size : 0;
  uploaded.push({ path: upload.repoPath, bytes, unchanged: putResult?.unchanged === true });
  if (upload.isImage) {
    uploadedImages.push({
      local_path: normalizeLocalRoot(upload.local),
      github_path: upload.repoPath,
      cdn_url: cdnUrl(owner, repo, branch, upload.repoPath)
    });
  }
}

const githubUrl = `https://github.com/${owner}/${repo}/tree/${branch}/products/${productId}`;
return [{ json: {
  ok: true,
  product_id: productId,
  owner,
  repo,
  branch,
  github_url: githubUrl,
  active_skill: activeSkill,
  custom_skill_path: input.custom_skill_path || '',
  generate_count: Math.max(1, Math.min(Number(input.generate_count || 1), 10)),
  dry_run: toBool(input.dry_run, true),
  auto_start_main: toBool(input.auto_start_main, false),
  uploaded,
  uploaded_images: uploadedImages,
  image_upload_warning: imageUploadWarning || null,
  warnings
} }];
